import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.C2zB12QK.js";const p=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),i={name:"explanation/decisions.md"};function o(r,e,l,c,d,u){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. The contracts are pinned by org-ledger ADRs — ADR-0003 (release semantics), ADR-0004 (tag-only</p><ul><li>tamias publish), ADR-0005 (tarsi as the release plane), P-030 (strategy tables).</li></ul><h2 id="ops-surface-not-a-cli" tabindex="-1">Ops surface, not a CLI <a class="header-anchor" href="#ops-surface-not-a-cli" aria-label="Permalink to &quot;Ops surface, not a CLI&quot;">​</a></h2><p><strong>Decision:</strong> there is no <code>tarsi</code> binary — <code>tarsi-serve</code> exposes ndjson ops plus a one-shot argv front door.</p><ul><li><em>Alternative:</em> a conventional clap CLI like every other engine.</li><li><em>Consequence:</em> humans, agents, and peregrin campaigns speak one wire; the surface is generatable (ops manifest → MCP/CLI tools). Cost: every interaction is a JSON round-trip, and <code>release.sh</code> shims exist per repo to keep the muscle memory.</li></ul><h2 id="dry-run-is-the-default" tabindex="-1">Dry-run is the default <a class="header-anchor" href="#dry-run-is-the-default" aria-label="Permalink to &quot;Dry-run is the default&quot;">​</a></h2><p><strong>Decision:</strong> <code>release</code>-family ops mutate only with <code>dry_run: false</code> (<code>--yes</code>).</p><ul><li><em>Alternative:</em> mutate by default, flag to preview.</li><li><em>Consequence:</em> agents and campaigns can probe any repo safely; the explicit opt-in mirrors &quot;service surfaces never mutate unless asked&quot; org-wide.</li></ul><h2 id="per-unit-tags-and-ranges" tabindex="-1">Per-unit tags and ranges <a class="header-anchor" href="#per-unit-tags-and-ranges" aria-label="Permalink to &quot;Per-unit tags and ranges&quot;">​</a></h2><p><strong>Decision:</strong> <code>{unit}-v{version}</code> tags; each unit&#39;s range is latest-tag-for-that-unit..HEAD.</p><ul><li><em>Alternative:</em> one repo-level <code>v{semver}</code>.</li><li><em>Consequence:</em> units in a workspace release independently and only when their paths changed — the common case for polyrepos.</li></ul><h2 id="strategy-as-data-not-code" tabindex="-1">Strategy as data, not code <a class="header-anchor" href="#strategy-as-data-not-code" aria-label="Permalink to &quot;Strategy as data, not code&quot;">​</a></h2><p><strong>Decision:</strong> bump inference and changelog sectioning are data-driven rule tables (<code>[release] strategy</code>), not a plugin API.</p><ul><li><em>Alternative:</em> executable plugins / per-repo code.</li><li><em>Consequence:</em> presets (<code>semantic-release-angular</code>, <code>keep-a-changelog</code>) ship as config; arbitrary types like <code>deps</code> are nameable. The documented P-030 boundary: non-semver versioning or plugin execution would need a different mechanism.</li></ul><h2 id="no-tarsi-llm" tabindex="-1">No <code>tarsi-llm</code> <a class="header-anchor" href="#no-tarsi-llm" aria-label="Permalink to &quot;No `tarsi-llm`&quot;">​</a></h2><p><strong>Decision:</strong> changelog polish composes with sepia sessions at the <em>caller</em>; tarsi itself never calls a model.</p><ul><li><em>Alternative:</em> an in-repo LLM path for nicer notes.</li><li><em>Consequence:</em> release semantics stay deterministic and auditable; the cuora/secrets boundary is untouched.</li></ul><h2 id="push-before-publish" tabindex="-1">Push before publish <a class="header-anchor" href="#push-before-publish" aria-label="Permalink to &quot;Push before publish&quot;">​</a></h2><p><strong>Decision:</strong> mutation order ends <code>push branch+tags → publish</code>.</p><ul><li><em>Alternative:</em> publish, then push.</li><li><em>Consequence:</em> GitHub Releases auto-creates missing tags at remote HEAD — pushing first keeps the tag pinned to the bumped commit. Load-bearing, pinned by ADR-0003.</li></ul>',21)])])}const m=a(i,[["render",o]]);export{p as __pageData,m as default};
